import csv, glob, os, re
from datetime import date, timedelta

TODAY = date(2025, 8, 12)
last7_start = TODAY - timedelta(days=6)    # 2025-08-06 .. 2025-08-12
last30_start = TODAY - timedelta(days=29)  # 2025-07-14 .. 2025-08-12
mtd_start = TODAY.replace(day=1)           # 2025-08-01 .. 2025-08-12

sevs = ["ERROR", "WARNING", "INFO"]
counts = {p: {s: 0 for s in sevs} for p in ["today","last_7_days","last_30_days","month_to_date","total"]}

fname_re = re.compile(r'^(\d{4}-\d{2}-\d{2})_[^.]+\.log$')
for path in glob.glob('/app/logs/*.log'):
    m = fname_re.match(os.path.basename(path))
    if not m:
        print(f"SKIP (unexpected name): {path}")
        continue
    d = date.fromisoformat(m.group(1))
    if d == TODAY:
        periods = ["today","last_7_days","last_30_days","month_to_date","total"]
    elif mtd_start <= d <= TODAY:
        periods = ["last_7_days","last_30_days","month_to_date","total"]
    elif last7_start <= d <= TODAY:
        periods = ["last_7_days","last_30_days","total"]
    elif last30_start <= d <= TODAY:
        periods = ["last_30_days","total"]
    else:
        periods = ["total"]
    with open(path, encoding="utf-8", errors="replace") as f:
        for line in f:
            # severity is the bracketed token, e.g. "[ERROR]"; match whole token
            mm = re.search(r'\[(ERROR|WARNING|INFO)\]', line)
            if mm:
                for p in periods:
                    counts[p][mm.group(1)] += 1

with open('/app/summary.csv', 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(["period","severity","count"])
    for p in ["today","last_7_days","last_30_days","month_to_date","total"]:
        for s in sevs:
            w.writerow([p, s, counts[p][s]])
print("written")
for p in ["today","last_7_days","last_30_days","month_to_date","total"]:
    print(p, counts[p])
EOF
python3 /tmp/analyze.py

